use vstd::prelude::*;

verus! {

    // Given an input vector `s` of exactly 19 characters,
    // where each character is either a lowercase letter 'a'..'z' or a comma ',',
    // and with guaranteed commas at positions 5 and 13,
    // produce a new vector of length 20 such that commas are replaced by spaces
    // and a newline '\n' is appended at the end.
    fn solve(s: Vec<char>) -> (result: Vec<char>)
        requires
            // Input length is exactly 19
            s.len() == 19,
            // Every character is either ',' or in 'a'..'z'
            forall |i: usize| i < 19 ==> (s[i] == ',' || ('a' <= s[i] && s[i] <= 'z')),
            // Commas at positions 5 and 13
            s[5]  == ',',
            s[13] == ',',
        ensures
            // Output length is 20
            result.len() == 20,
            // Last character is newline
            result[19] == '\n',
            // For i in 0..19, commas are replaced by spaces, else preserved
            forall |i: usize| i < 19 ==>
                result[i] == if s[i] == ',' { ' ' } else { s[i] },
    {
        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;
        // Build up res[0..i) character by character
        while i < 19
            invariant
                // `i` never exceeds 19
                i <= 19,
                // We've pushed exactly `i` characters so far
                res.len() == i,
                // The first `i` chars satisfy the desired mapping
                forall |j: usize| j < i ==>
                    res[j] == if s[j] == ',' { ' ' } else { s[j] },
            decreases 19 - i,
        {
            let c = s[i];
            if c == ',' {
                res.push(' ');
            } else {
                res.push(c);
            }
            i = i + 1;
        }
        // Append the newline
        res.push('\n');
        // Return the constructed vector
        res
    }

}

